findings.suggested_fix:
In `infra/terraform/iam.tf` (or `iam_s3_bedrock.tf`), add:
```hcl
data "aws_iam_policy_document" "bedrock_invoke" {
  statement {
    sid = "BedrockInvokeClaudeModels"
    actions = [
      "bedrock:InvokeModel",
      "bedrock:InvokeModelWithResponseStream",
    ]
    resources = [
      "arn:aws:bedrock:${var.aws_region}::foundation-model/anthropic.claude-*",
      # If using cross-region inference profiles, also:
      # "arn:aws:bedrock:${var.aws_region}:${data.aws_caller_identity.current.account_id}:inference-profile/*",
    ]
  }
}

resource "aws_iam_role_policy" "bedrock_invoke" {
  name   = "rebar-gerrit-bedrock-invoke"
  role   = aws_iam_role.gerrit_instance.id
  policy = data.aws_iam_policy_document.bedrock_invoke.json
}
```
